package in.carenest.clinic.api;
import in.carenest.clinic.security.SecurityConfig.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.sql.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api") public class ClinicApi {
 private final JdbcTemplate db; private final JwtService jwt; public ClinicApi(JdbcTemplate db,JwtService jwt){this.db=db;this.jwt=jwt;}
 public record Login(@NotBlank String username,@NotBlank String password){} public record Session(String token,Map<String,Object> user){}
 @PostMapping("/auth/login") public Session login(@Valid @RequestBody Login x){var rows=db.query("select id,clinic_id,branch_id,display_name,role from users where username=? and active and password_hash=crypt(?,password_hash)",(r,n)->new TenantPrincipal(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getObject(3,UUID.class),r.getString(5),r.getString(4)),x.username(),x.password());if(rows.isEmpty())throw new ApiError(HttpStatus.UNAUTHORIZED,"Invalid username or password");var p=rows.getFirst();return new Session(jwt.issue(p),Map.of("id",p.userId(),"name",p.name(),"role",p.role(),"clinicId",Objects.toString(p.clinicId(),""),"branchId",Objects.toString(p.branchId(),"")));}
 @GetMapping("/dashboard") public Map<String,Object> dashboard(@AuthenticationPrincipal TenantPrincipal p,@RequestParam(required=false) LocalDate date){tenant(p);LocalDate d=date==null?LocalDate.now():date;var counts=db.queryForMap("select count(*) filter(where status='BOOKED') appointments,coalesce(sum(price) filter(where status in('BOOKED','DONE')),0) expected,count(distinct room_id) filter(where status='BOOKED') rooms from appointments where clinic_id=? and starts_at>=? and starts_at<?",p.clinicId(),d.atStartOfDay(),d.plusDays(1).atStartOfDay());var upcoming=db.queryForList("select a.id,a.starts_at,c.full_name customer,s.name service,pr.full_name practitioner,r.name room,a.status from appointments a join customers c on c.id=a.customer_id join services s on s.id=a.service_id join practitioners pr on pr.id=a.practitioner_id join rooms r on r.id=a.room_id where a.clinic_id=? and a.starts_at>=? and a.starts_at<? order by a.starts_at",p.clinicId(),d.atStartOfDay(),d.plusDays(1).atStartOfDay());return Map.of("summary",counts,"appointments",upcoming);}
 @GetMapping("/services") public List<Map<String,Object>> services(@AuthenticationPrincipal TenantPrincipal p){tenant(p);return db.queryForList("select id,name,category,room_type,minutes,price,discount_percent,active from services where clinic_id=? order by name",p.clinicId());}
 @GetMapping("/customers") public List<Map<String,Object>> customers(@AuthenticationPrincipal TenantPrincipal p,@RequestParam(defaultValue="") String q){tenant(p);return db.queryForList("select id,full_name,phone,email,joined_on,free_cancellations_remaining from customers where clinic_id=? and lower(full_name) like lower(?) order by full_name limit 100",p.clinicId(),"%"+q+"%");}
 public record Customer(@NotBlank String fullName,@NotBlank String phone,String email,LocalDate dob,String guardianName,String guardianPhone){}
 @PostMapping("/customers") @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> addCustomer(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody Customer x){tenant(p);UUID id=UUID.randomUUID();db.update("insert into customers(id,clinic_id,branch_id,full_name,phone,email,dob,guardian_name,guardian_phone,free_cancellations_remaining) select ?,?,?,?,?,?,?,?,?,free_customer_cancellations from clinics where id=?",id,p.clinicId(),p.branchId(),x.fullName(),x.phone(),x.email(),x.dob(),x.guardianName(),x.guardianPhone(),p.clinicId());return Map.of("id",id);}
 public record Booking(@NotNull UUID customerId,@NotNull UUID practitionerId,@NotNull UUID serviceId,@NotNull LocalDateTime startsAt){}
 @PostMapping("/appointments") @Transactional public Map<String,Object> book(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody Booking x){tenant(p);db.queryForObject("select pg_advisory_xact_lock(hashtextextended(?,0))",Long.class,p.branchId()+"|"+x.startsAt());var service=db.queryForMap("select room_type,minutes,price from services where id=? and clinic_id=? and active",x.serviceId(),p.clinicId());int mins=(Integer)service.get("minutes");LocalDateTime end=x.startsAt().plusMinutes(mins);Integer partnerBusy=db.queryForObject("select count(*) from appointments where clinic_id=? and practitioner_id=? and status='BOOKED' and starts_at<? and ends_at>?",Integer.class,p.clinicId(),x.practitionerId(),end,x.startsAt());if(partnerBusy!=null&&partnerBusy>0)throw new ApiError(HttpStatus.CONFLICT,"Practitioner is not available for this slot");var rooms=db.queryForList("select r.id from rooms r where r.clinic_id=? and r.branch_id=? and r.room_type=? and r.active and not exists(select 1 from appointments a where a.room_id=r.id and a.status='BOOKED' and a.starts_at<? and a.ends_at>?) order by r.name limit 1",UUID.class,p.clinicId(),p.branchId(),service.get("room_type"),end,x.startsAt());if(rooms.isEmpty())throw new ApiError(HttpStatus.CONFLICT,"No suitable room is available for this slot");UUID id=UUID.randomUUID();db.update("insert into appointments(id,clinic_id,branch_id,customer_id,practitioner_id,service_id,room_id,starts_at,ends_at,price,booked_by) values(?,?,?,?,?,?,?,?,?,?,?)",id,p.clinicId(),p.branchId(),x.customerId(),x.practitionerId(),x.serviceId(),rooms.getFirst(),x.startsAt(),end,service.get("price"),p.userId());db.update("insert into booking_events(clinic_id,appointment_id,event_type,actor_user_id,new_values) values(?,?,'BOOKED',?,jsonb_build_object('startsAt',?::text))",p.clinicId(),id,p.userId(),x.startsAt().toString());return Map.of("id",id,"roomId",rooms.getFirst(),"endsAt",end,"status","BOOKED");}
 public record Cancel(String reason,@NotNull String cancelledBy){}
 @PostMapping("/appointments/{id}/cancel") @Transactional public Map<String,Object> cancel(@AuthenticationPrincipal TenantPrincipal p,@PathVariable UUID id,@RequestBody Cancel x){tenant(p);var a=db.queryForMap("select starts_at,price,customer_id,status from appointments where id=? and clinic_id=? for update",id,p.clinicId());if(!"BOOKED".equals(a.get("status")))throw new ApiError(HttpStatus.CONFLICT,"Only booked appointments can be cancelled");boolean practitioner="PRACTITIONER".equalsIgnoreCase(x.cancelledBy());long notice=Duration.between(LocalDateTime.now(),((Timestamp)a.get("starts_at")).toLocalDateTime()).toHours();int free=db.queryForObject("select free_customer_cancellations_remaining from customers where id=?",Integer.class,a.get("customer_id"));int required=db.queryForObject("select cancellation_notice_hours from clinics where id=?",Integer.class,p.clinicId());BigDecimal charge=BigDecimal.ZERO;if(!practitioner&&notice<required){if(free>0)db.update("update customers set free_cancellations_remaining=free_cancellations_remaining-1 where id=?",a.get("customer_id"));else charge=(BigDecimal)a.get("price");}if(practitioner)db.update("update customers set free_cancellations_remaining=free_cancellations_remaining+(select practitioner_cancel_credit from clinics where id=?) where id=?",p.clinicId(),a.get("customer_id"));db.update("update appointments set status='CANCELLED',version=version+1 where id=?",id);db.update("insert into booking_events(clinic_id,appointment_id,event_type,actor_user_id,charge,new_values) values(?,?,'CANCELLED',?,?,jsonb_build_object('reason',?))",p.clinicId(),id,p.userId(),charge,x.reason());return Map.of("status","CANCELLED","charge",charge);}
 public record ConfirmPayment(@NotNull UUID customerId,@DecimalMin("0.01") BigDecimal amount,@NotBlank String otp,@NotBlank String method){}
 @PostMapping("/payments/confirm") @Transactional public Map<String,Object> pay(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody ConfirmPayment x){tenant(p);Boolean ok=db.queryForObject("select payment_otp_hash=crypt(?,payment_otp_hash) from clinics where id=?",Boolean.class,x.otp(),p.clinicId());if(!Boolean.TRUE.equals(ok))throw new ApiError(HttpStatus.UNAUTHORIZED,"Invalid payment confirmation OTP");UUID id=UUID.randomUUID();String receipt="RCPT-"+LocalDate.now().getYear()+"-"+id.toString().substring(0,8).toUpperCase();db.update("insert into payments(id,clinic_id,branch_id,customer_id,amount,status,method,receipt_number,confirmed_at,confirmed_by) values(?,?,?,?,?,'CONFIRMED',?,?,now(),?)",id,p.clinicId(),p.branchId(),x.customerId(),x.amount(),x.method(),receipt,p.userId());return Map.of("id",id,"receiptNumber",receipt,"whatsappStatus","QUEUED");}
 private void tenant(TenantPrincipal p){if(p==null||p.clinicId()==null)throw new ApiError(HttpStatus.FORBIDDEN,"A clinic context is required");}
 @ResponseStatus class ApiError extends RuntimeException{final HttpStatus status;ApiError(HttpStatus s,String m){super(m);status=s;}}
 @ExceptionHandler(ApiError.class) ResponseEntity<?> error(ApiError e){return ResponseEntity.status(e.status).body(Map.of("error",e.getMessage()));}
}
